import{_ as e,o as t,c as i,ag as l}from"./chunks/framework.ePeAWSvT.js";const _=JSON.parse('{"title":"如何避免测试集泄漏与无效高分","description":"用三个真实实验说明可靠评估比漂亮数字更重要。","frontmatter":{"title":"如何避免测试集泄漏与无效高分","description":"用三个真实实验说明可靠评估比漂亮数字更重要。"},"headers":[],"relativePath":"posts/evaluation-without-leakage.md","filePath":"posts/evaluation-without-leakage.md","lastUpdated":1786688709000}'),o={name:"posts/evaluation-without-leakage.md"};function r(p,a,n,s,h,c){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="如何避免测试集泄漏与无效高分" tabindex="-1">如何避免测试集泄漏与无效高分 <a class="header-anchor" href="#如何避免测试集泄漏与无效高分" aria-label="Permalink to &quot;如何避免测试集泄漏与无效高分&quot;">​</a></h1><p>深度学习项目最容易美化的部分是准确率，也最容易因为实验设计失去意义。整理自己的五个 Notebook 时，我遇到了三类典型问题。</p><h2 id="_1-每个-epoch-看测试集" tabindex="-1">1. 每个 epoch 看测试集 <a class="header-anchor" href="#_1-每个-epoch-看测试集" aria-label="Permalink to &quot;1. 每个 epoch 看测试集&quot;">​</a></h2><p>如果训练过程中不断查看测试准确率，再据此选择学习率、epoch 或模型版本，测试集已经间接参与了训练决策。</p><p>更合理的分工是：</p><ul><li>训练集更新参数；</li><li>验证集比较超参数和选择 checkpoint；</li><li>测试集在所有决策固定后只做最终评估。</li></ul><p>因此，我把 MLP 和 ResNet 实验改为 validation-first 流程。</p><h2 id="_2-随机图片-随机标签得到-96-5" tabindex="-1">2. 随机图片 + 随机标签得到 96.5% <a class="header-anchor" href="#_2-随机图片-随机标签得到-96-5" aria-label="Permalink to &quot;2. 随机图片 + 随机标签得到 96.5%&quot;">​</a></h2><p>Residual + LayerNorm 实验在 500 张随机图片和随机标签上训练，训练准确率最终达到 96.5%。这不能说明模型学会了视觉分类，只说明网络有能力记住有限样本。</p><p>这个实验仍有价值，但价值在于检查残差结构、参数共享、checkpoint 和设备行为。正确做法是把它标为 systems lab，而不是分类 benchmark。</p><h2 id="_3-四张测试图片得到-75" tabindex="-1">3. 四张测试图片得到 75% <a class="header-anchor" href="#_3-四张测试图片得到-75" aria-label="Permalink to &quot;3. 四张测试图片得到 75%&quot;">​</a></h2><p>猫狗迁移学习 Demo 的测试集只有四张原图。75% 实际上只是 3/4；再多或少预测对一张，结果就会变化 25 个百分点。</p><p>它可以证明训练、微调、混淆矩阵和 Grad-CAM 管线能够运行，却不足以证明模型泛化能力。要形成可靠结论，需要更大的分层测试集、每类支持数和置信区间。</p><h2 id="_4-我的项目检查清单" tabindex="-1">4. 我的项目检查清单 <a class="header-anchor" href="#_4-我的项目检查清单" aria-label="Permalink to &quot;4. 我的项目检查清单&quot;">​</a></h2><p>提交一个实验前，我现在会检查：</p><ul><li>[ ] 数据划分是否在训练开始前固定？</li><li>[ ] 测试集是否参与了超参数选择？</li><li>[ ] 对比模型是否共享初始化、数据顺序和计算预算？</li><li>[ ] 指标的样本量是否足够？</li><li>[ ] 训练准确率是否被误写成泛化性能？</li><li>[ ] CPU、CUDA 和 FlashAttention 结论是否区分环境？</li><li>[ ] 失败、跳过项和局限是否写在结果旁边？</li></ul><p>一个可信的 68.8%，通常比来源不清楚的 95% 更有说服力。面试中真正能展开讨论的，也往往是你如何发现并修正这些问题。</p>',17)])])}const u=e(o,[["render",r]]);export{_ as __pageData,u as default};
